/* Prove the in-browser auditor agrees with dmarcsight, finding for finding.
 *
 *     node build/parity.mjs
 *
 * The fixtures are generated by build/export_audit_fixtures.py from the real
 * Python package. If this fails, the two implementations have drifted and the
 * site is about to tell someone something the tool would not.
 */
import { readFileSync } from 'node:fs';
import { audit } from './js/audit.js';

const fixtures = JSON.parse(readFileSync(new URL('./audit_fixtures.json', import.meta.url)));

function fixtureResolver({ txt = {}, mx = {}, a = {} }) {
  const strip = n => n.replace(/\.+$/, '');
  return {
    txt: async n => txt[strip(n)] || [],
    mx:  async n => mx[strip(n)] || [],
    a:   async n => a[strip(n)] || [],
  };
}
const noFetch = async () => [null, 'fetch disabled in fixtures'];

let failed = 0, checked = 0;
for (const f of fixtures) {
  const rep = await audit('example.com', fixtureResolver(f), noFetch, f.selectors);
  const got = rep.findings.map(x => [x.check, x.severity, x.finding, x.remediation, x.detail]);
  checked += f.expected.length;
  if (JSON.stringify(got) !== JSON.stringify(f.expected)) {
    failed++;
    console.error(`\nDRIFT in "${f.name}"`);
    const n = Math.max(got.length, f.expected.length);
    for (let i = 0; i < n; i++) {
      const a = JSON.stringify(f.expected[i]), b = JSON.stringify(got[i]);
      if (a !== b) {
        console.error(`  python: ${a}`);
        console.error(`  js:     ${b}`);
      }
    }
  }
}

if (failed) {
  console.error(`\n${failed}/${fixtures.length} scenarios differ`);
  process.exit(1);
}
console.log(`  parity ok (${fixtures.length} scenarios, ${checked} findings)`);
